"""Explain atomic ordering and conditional reads in beginner Korean."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1621': ('한 사람이 번호표를 바꾸는 일과, 다른 사람이 안내문까지 올바른 순서로 보는 일은 다른 약속이에요. 원자성과 메모리 순서도 나누어 생각해요.', '복합 원자 연산의 읽기·쓰기와 acquire·release의 역할을 구별합니다.', '읽기 → 계산 → 쓰기를 그리세요. acquire는 읽기 쪽, release는 쓰기 쪽에 표시하고, 실패한 비교에는 acquire 보장 없음이라고 적으세요.', ['원자 연산은 정해진 값의 변경이 중간에 쪼개져 관찰되지 않도록 다뤄요. 그러나 그 옆에 있는 다른 데이터까지 원하는 순서로 보인다는 뜻은 아니에요. 번호표 변경과 안내문 공개를 별도로 생각하는 이유예요.', '복합 연산은 값을 읽고 계산한 뒤 쓰는 일을 함께 하는 연산이에요. 예를 들어 4를 읽어 1을 더하고 5를 저장해요. 여기서는 읽기를 R, 쓰기를 W라고 줄여 부를 수 있어요.', 'acquire는 가져와 확인하는 쪽의 순서 약속이에요. 복합 연산에서는 읽기 부분에 적용돼요. 올바른 공개 규칙과 짝지으면 그 읽기 뒤에 데이터를 사용하는 순서를 지키는 데 쓰여요. 복합 연산의 쓰기 부분까지 acquire로 설명하지 않아요.', 'release는 내놓는 쪽의 순서 약속이에요. 복합 연산의 쓰기 부분에 적용돼요. 예를 들어 안내문 내용을 먼저 채우고 준비 표시를 release로 공개하는 식이에요. 읽는 쪽도 알맞은 acquire와 같은 공개 값을 관찰하는 규칙을 지켜야 해요.', '여기서 다루는 교환 연산 등의 relaxed 형태는 다른 메모리 접근에 대한 순서를 약속하지 않아요. 공통 도우미는 relaxed 연산 뒤에 acquire 장벽을, 앞에 release 장벽을 붙여요. full 도우미는 앞뒤에 장벽을 붙여요. 장벽은 이 순서 관계를 보강하는 도구이지 모든 값을 잠그는 자물쇠가 아니에요.', 'cmpxchg는 현재 값이 예상과 같을 때만 바꿔요. cmpxchg_acquire가 비교에 실패했을 때는 acquire 순서를 보장한다고 의존하면 안 돼요. 특정 CPU용 구현에서 더 강한 장벽을 거칠 수 있어도, 모든 구현이 반드시 그럴 것이라는 약속은 없어요.'], [('읽고 계산하고 쓰는 복합 연산에서 acquire 약속은 어느 부분에 적용되나요?', ['읽기와 쓰기 모두에 똑같이 적용돼요', '읽기 부분에 적용돼요'], '정답은 두 번째예요. acquire는 읽은 뒤 이어지는 접근의 순서를 다루고, release는 쓰기 쪽의 약속이에요. 하나의 복합 연산이라고 두 부분의 역할까지 같은 것은 아니에요.'), ('cmpxchg_acquire가 비교에 실패했어요. 이름만 보고 acquire 순서가 보장된다고 생각해도 될까요?', ['아니요. 실패한 경우에는 그 보장을 기대하면 안 돼요', '네. 이름에 acquire가 있으면 실패해도 항상 보장돼요'], '정답은 첫 번째예요. 원문은 실패한 cmpxchg_acquire에 순서 보장을 기대하지 말라고 명시해요. 일부 구현이 더 강하게 동작해도 모든 구현의 약속으로 넓힐 수 없어요.')]), 'os1622': ('전광판 숫자가 3이 될 때까지 확인한 뒤, 마지막에 본 숫자 3을 메모한다고 생각해 보세요. 결과는 맞다라는 말이 아니라 실제로 본 숫자예요.', '조건부 읽기의 VAL과 반환값을 이해합니다.', '관찰값 0 → 1 → 3을 쓰고 VAL == 3을 각각 검사하세요. 마지막 반환값은 3이라고 적으세요.', ['atomic 객체는 숫자를 담는 counter라는 칸을 가지고 있어요. atomic_cond_read_relaxed(v, c)는 그 칸의 주소를 조건부 읽기 도구에 전달해요. &(v)->counter의 &는 칸이 있는 위치, 즉 주소를 구하는 표시예요.', '공통 구현은 주소를 __PTR에 보관하고 그 위치에서 READ_ONCE로 값을 읽어요. 읽은 값은 VAL이라는 정해진 이름의 임시 칸에 넣어요. 조건식에서 사용할 값의 이름을 미리 맞춰 놓은 것이에요.', '조건식이 VAL == 3이면 방금 읽은 숫자가 3과 같은지 묻는 뜻이에요. ==는 같은지 비교하고, =는 값을 넣을 때 써요. VAL이 0이면 조건이 거짓이고, 3이면 참이에요.', '값 읽기 → 조건 확인을 반복하다 참이 되면 반복을 끝내요. 첫 번째 읽기부터 3이었다면 추가로 기다릴 필요가 없어요. 읽은 값이 0, 1, 3 순이었다면 세 번째 확인에서 끝나요.', '마지막 식은 조건을 만족시킨 VAL을 돌려줘요. 그래서 VAL == 3을 만족했다면 반환값은 3이에요. 조건이 참이라는 뜻으로 무조건 1을 반환하는 도구가 아니에요. VAL >= 3에서 5를 관찰했다면 5를 돌려줘요.', '돌려받은 숫자는 그 순간 읽은 기록이에요. 다른 실행 흐름이 이후 값을 바꿀 수 있으므로 숫자를 얼려 두는 기능은 아니에요. relaxed 읽기만으로 다른 데이터의 공개 순서나 객체가 계속 살아 있는 기간까지 보장하지도 않아요. CPU별 구현은 이 공통 코드와 다른 방식으로 같은 기능을 제공할 수 있어요.'], [('조건식에서 방금 읽은 숫자를 사용하려면 어떤 이름을 쓰나요?', ['sizeof라는 이름이에요', 'VAL이라는 이름이에요'], '정답은 두 번째예요. 공통 구현이 읽은 숫자를 VAL에 넣고 조건식을 검사해요. sizeof는 자료형이나 값이 차지하는 크기를 구하는 C 연산자여서 여기서 읽은 숫자의 이름이 아니에요.'), ('VAL == 3 조건을 만족해서 기다림을 끝냈어요. 무엇을 돌려주나요?', ['마지막에 읽은 숫자 3이에요', '조건이 참이므로 언제나 숫자 1이에요'], '정답은 첫 번째예요. 조건 검사는 반복을 끝낼지 정해 주고, 반환은 마지막 읽은 값 VAL을 전달해요. 조건의 참·거짓과 읽어 온 숫자를 구별하세요.')]), 'os1623': ('친구가 올 때까지 창문을 계속 확인하는 방법과, 도착하면 깨워 달라고 부탁하고 자는 방법은 달라요. 여기서는 계속 확인하는 쪽을 배워요.', '반복 확인과 잠드는 대기를 구별하고 종료 조건을 이해합니다.', '관찰값 0, 0, 3과 조건 VAL == 3을 적으세요. 앞의 두 번은 cpu_relax 뒤 다시 읽고, 마지막에는 끝나는 화살표를 그리세요.', ['spin 대기는 조건이 맞을 때까지 계속 확인하는 방법이에요. 공통 smp_cond_load_relaxed는 값을 읽고 조건을 검사해요. 맞지 않으면 cpu_relax를 거친 뒤 다시 읽어요.', 'cpu_relax는 이런 반복 대기에 쓰는 CPU별 도우미예요. 이름의 relax가 편히 쉰다는 느낌이어도, 이 코드가 잠자는 작업 목록에 들어가거나 정해진 초 동안 수면한다는 뜻은 아니에요.', '잠드는 대기는 기다리는 작업을 등록하고 다른 작업이 CPU를 쓰게 하는 절차를 이용할 수 있어요. wait queue는 이렇게 기다리는 작업들을 관리하는 목록이에요. 이 공통 반복문 자체에는 그런 등록이나 schedule 호출이 없어요.', '종이에 0, 0, 3을 차례로 읽었다고 가정해 보세요. 조건이 VAL == 3이면 첫 두 번에는 cpu_relax 뒤 다시 읽고, 세 번째에는 끝나요. 이것은 순서를 이해하는 예시이고 실제 실행에서 반드시 세 번 만에 값이 바뀐다는 예측은 아니에요.', '값이 계속 0이고 조건이 계속 거짓이면 반복도 계속돼요. 이 도구에는 1초가 지나면 종료 같은 제한 시간 인자가 없어요. 시간을 넘기면 중단하는 기능을 timeout이라고 하는데 여기서 자동으로 제공하지 않아요.', '사용 전에 누가 값을 바꿔 줄지, 그 작업이 실제로 실행될 수 있는지 생각해야 해요. 내가 잡은 잠금을 상대도 필요로 한다면 상대가 값을 바꾸지 못할 수도 있어요. 짧은 반복 대기와 긴 수면 대기 중 무엇을 쓸지는 이런 실행 조건과 기다리는 길이에 맞춰 정해야 해요.'], [('이 공통 조건부 읽기 반복문은 조건이 거짓이면 어떻게 하나요?', ['자동으로 wait queue에 등록하고 잠들어요', 'cpu_relax를 거친 뒤 READ_ONCE로 다시 읽어요'], '정답은 두 번째예요. 원문 반복문은 읽기 → 조건 검사 → cpu_relax → 다시 읽기의 흐름이에요. 작업을 수면 목록에 넣는 코드는 여기에 없어요.'), ('조건이 계속 거짓이면 이 도구가 자동으로 1초 뒤 종료하나요?', ['아니요. 자동 제한 시간이 없어서 계속 반복할 수 있어요', '네. 모든 cpu_relax는 1초 뒤 반복을 끝내요'], '정답은 첫 번째예요. 이 매크로에는 제한 시간을 받거나 검사하는 단계가 없어요. cpu_relax는 반복을 종료시키는 타이머가 아니므로 조건을 바꾸는 쪽의 진행이 중요해요.')]), 'os1624': ('준비 표시를 확인한 뒤 내용물을 읽는 순서를 지켜야 해요. 표시 확인과 그 뒤의 읽기 사이에 어떤 약속을 넣는지 따라가 봐요.', '조건부 acquire의 조건 관찰·순서 보강·결과 반환을 구별합니다.', '조건이 맞을 때까지 읽기 → smp_acquire__after_ctrl_dep → 읽은 값 반환을 그리세요. 값 3이 마지막까지 보존되는지 표시하세요.', ['atomic_cond_read_acquire는 atomic 객체의 counter 주소를 smp_cond_load_acquire에 전달해요. counter는 숫자 칸이고, 주소는 그 칸이 메모리 어디에 있는지 알려 주는 값이에요.', '공통 구현은 먼저 smp_cond_load_relaxed로 조건을 만족할 때까지 읽어요. 조건이 맞은 순간의 값을 _val이라는 임시 칸에 보관해요. 예를 들어 VAL == 3을 만족했다면 _val에는 3이 들어 있어요.', '그 다음 smp_acquire__after_ctrl_dep를 호출해요. 긴 이름을 나누면 조건에 따른 진행 결정 뒤에 acquire 순서를 보강한다는 뜻이에요. control dependency는 읽은 값에 따라 다음 단계로 갈지 결정하는 관계예요.', '조건에 따른 진행 결정만으로 뒤의 모든 읽기 순서까지 충분해지는 것은 아니에요. 공통 도우미는 필요한 읽기 순서를 장벽으로 보강해요. 그래서 조건을 만족한 읽기와 그 뒤의 데이터 접근을 acquire 규칙으로 연결할 수 있어요.', '순서를 보강한 뒤 처음 저장해 둔 _val을 반환해요. 3을 관찰했다면 결과도 3이에요. 중간 장벽은 그 값을 1로 바꾸거나 새 값을 다시 읽는 단계가 아니에요. 준비 표시와 데이터 공개를 연결하려면 작성 쪽의 release 등 올바른 동기화 규칙도 필요해요.', 'CPU 종류마다 필요한 장벽 구현은 달라질 수 있어요. 이 도우미가 호출된 것을 확인했다고 모든 CPU가 똑같은 기계 명령을 실행했다고 결론 내릴 수 없어요. 공통 코드의 순서 약속과 CPU별로 그 약속을 실현하는 방법을 나누어 읽으세요.'], [('공통 acquire 조건부 읽기는 relaxed 조건부 읽기 뒤에 무엇을 호출하나요?', ['schedule_timeout으로 정해진 시간 동안 잠들어요', 'smp_acquire__after_ctrl_dep로 순서를 보강해요'], '정답은 두 번째예요. 조건을 만족한 값을 저장하고 순서 보강 도우미를 거친 뒤 그 값을 반환해요. 이 경로는 schedule_timeout으로 수면하는 흐름이 아니에요.'), ('순서 보강 도우미를 호출했다는 기록만으로 모든 CPU가 같은 명령을 실행했다고 할 수 있나요?', ['아니요. CPU별 실제 구현을 따로 확인해야 해요', '네. acquire라는 이름은 언제나 같은 기계 명령이에요'], '정답은 첫 번째예요. 공통 이름은 지켜야 할 순서 규칙을 나타내요. CPU에 따라 그 규칙을 구현하는 장벽이나 명령이 달라질 수 있어요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_401.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
